import heapq

def dijkstra_shortest_path(graph, source):
    vertices = set(graph.keys())
    for edges in graph.values():
        for v, _ in edges:
            vertices.add(v)
    vertices.add(source)
    dist = {v: float('inf') for v in vertices}
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist

from typing import Optional, List, Tuple, Union

Token = Tuple[str, Optional[float]]

def evaluate_expression(expression: str) -> Optional[float]:
    def tokenize(s: str) -> List[Token]:
        tokens: List[Token] = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                start = i
                while i < n and s[i].isdigit():
                    i += 1
                tokens.append(("NUM", float(s[start:i])))
                continue
            if c in "+-*/()":
                tokens.append((c, None))
                i += 1
                continue
            raise ValueError("Invalid character")
        tokens.append(("EOF", None))
        return tokens

    class Parser:
        def __init__(self, tokens: List[Token]):
            self.tokens = tokens
            self.pos = 0

        def peek(self) -> str:
            return self.tokens[self.pos][0]

        def get(self) -> Token:
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

        def expect(self, t: str) -> None:
            if self.peek() != t:
                raise ValueError("Unexpected token")
            self.get()

        def parse_expression(self) -> float:
            value = self.parse_term()
            while self.peek() in ("+", "-"):
                op = self.get()[0]
                rhs = self.parse_term()
                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            return value

        def parse_term(self) -> float:
            value = self.parse_unary()
            while self.peek() in ("*", "/"):
                op = self.get()[0]
                rhs = self.parse_unary()
                if op == "*":
                    value *= rhs
                else:
                    if rhs == 0.0:
                        raise ZeroDivisionError
                    value /= rhs
            return value

        def parse_unary(self) -> float:
            if self.peek() == "+":
                self.get()
                return +self.parse_unary()
            if self.peek() == "-":
                self.get()
                return -self.parse_unary()
            return self.parse_primary()

        def parse_primary(self) -> float:
            t = self.peek()
            if t == "NUM":
                val = self.get()[1]
                if val is None:
                    raise ValueError("Missing number")
                return val
            if t == "(":
                self.get()
                val = self.parse_expression()
                self.expect(")")
                return val
            raise ValueError("Expected number or '('")

    try:
        if not isinstance(expression, str):
            return None
        tokens = tokenize(expression)
        parser = Parser(tokens)
        result = parser.parse_expression()
        if parser.peek() != "EOF":
            return None
        return float(result)
    except (ValueError, ZeroDivisionError):
        return None

def knapsack_01(items, capacity):
    if capacity <= 0 or not items:
        return 0
    dp = [0] * (capacity + 1)
    for wt, val in items:
        if wt < 0:
            continue
        for w in range(capacity, wt - 1, -1):
            cand = dp[w - wt] + val
            if cand > dp[w]:
                dp[w] = cand
    return dp[capacity]

