def longest_increasing_subsequence(nums):
    if not nums:
        return 0
    n = len(nums)
    # dp[i] = length of LIS ending at i (including nums[i])
    dp = [1] * n
    max_len = 1
    for i in range(1, n):
        ai = nums[i]
        best = 1
        # Compare with all previous elements
        for j in range(i):
            if nums[j] < ai:
                cand = dp[j] + 1
                if cand > best:
                    best = cand
        dp[i] = best
        if best > max_len:
            max_len = best
    return max_len

