def LRUCache(capacity):
    class _Node:
        __slots__ = ("key", "val", "prev", "next")
        def __init__(self, key=0, val=0):
            self.key = key
            self.val = val
            self.prev = None
            self.next = None

    class _LRU:
        def __init__(self, cap: int):
            self.cap = int(cap)
            self.map = {}
            self.head = _Node()  # sentinel head (most recent after head)
            self.tail = _Node()  # sentinel tail (least recent before tail)
            self.head.next = self.tail
            self.tail.prev = self.head

        def _add_to_front(self, node: _Node) -> None:
            node.prev = self.head
            node.next = self.head.next
            self.head.next.prev = node
            self.head.next = node

        def _remove_node(self, node: _Node) -> None:
            prev, nxt = node.prev, node.next
            prev.next = nxt
            nxt.prev = prev
            node.prev = node.next = None

        def _move_to_front(self, node: _Node) -> None:
            self._remove_node(node)
            self._add_to_front(node)

        def _pop_tail(self) -> _Node:
            lru = self.tail.prev
            if lru is self.head:
                return None
            self._remove_node(lru)
            return lru

        def get(self, key: int) -> int:
            node = self.map.get(key)
            if not node:
                return -1
            self._move_to_front(node)
            return node.val

        def put(self, key: int, value: int) -> None:
            if self.cap <= 0:
                return
            node = self.map.get(key)
            if node:
                node.val = value
                self._move_to_front(node)
                return
            new_node = _Node(key, value)
            self.map[key] = new_node
            self._add_to_front(new_node)
            if len(self.map) > self.cap:
                evicted = self._pop_tail()
                if evicted is not None:
                    self.map.pop(evicted.key, None)

    return _LRU(capacity)

