def dijkstra_shortest_path(graph, source):
    import heapq

    # Handle empty or falsy graph
    if not graph:
        return {}

    # Collect all vertices (including those appearing only as neighbors)
    vertices = set(graph.keys())
    for u, adj in graph.items():
        # Ensure adjacency is iterable; if not, treat as empty
        if adj is None:
            continue
        for v, w in adj:
            vertices.add(v)

    if not vertices:
        return {}

    # Initialize distances
    INF = float('inf')
    dist = {v: INF for v in vertices}

    # If source is a known vertex, initialize and run Dijkstra; else, return all infinities
    if source in vertices:
        dist[source] = 0.0
        pq = [(0.0, source)]
        visited = set()

        while pq:
            curr_d, u = heapq.heappop(pq)
            if u in visited:
                continue
            visited.add(u)

            # If popped distance is stale, skip
            if curr_d > dist[u]:
                continue

            for v, w in graph.get(u, []):
                # Skip edges with non-numeric weights gracefully
                try:
                    nd = curr_d + w
                except TypeError:
                    continue
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

    return dist
