def evaluate_expression(expression):
    if not isinstance(expression, str):
        return None
    s = expression
    n = len(s)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip_ws()
        return s[i] if i < n else ''

    def consume(expected=None):
        nonlocal i
        skip_ws()
        if i >= n:
            return ''
        ch = s[i]
        if expected is not None and ch != expected:
            raise ValueError("Expected '{}'".format(expected))
        i += 1
        return ch

    def parse_number():
        nonlocal i
        skip_ws()
        start = i
        # digits only (integers per problem)
        if i < n and s[i].isdigit():
            while i < n and s[i].isdigit():
                i += 1
            num_str = s[start:i]
            try:
                return float(int(num_str))
            except Exception:
                raise ValueError("Invalid number")
        else:
            raise ValueError("Number expected")

    def parse_primary():
        ch = peek()
        if ch == '(':
            consume('(')
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Missing ')'")
            consume(')')
            return val
        else:
            return parse_number()

    def parse_unary():
        ch = peek()
        if ch == '+' or ch == '-':
            op = consume()
            val = parse_unary()
            return val if op == '+' else -val
        return parse_primary()

    def parse_term():
        left = parse_unary()
        while True:
            ch = peek()
            if ch == '*' or ch == '/':
                op = consume()
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0.0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_expr():
        left = parse_term()
        while True:
            ch = peek()
            if ch == '+' or ch == '-':
                op = consume()
                right = parse_term()
                left = left + right if op == '+' else left - right
            else:
                break
        return left

    try:
        skip_ws()
        if i >= n:
            return None
        result = parse_expr()
        skip_ws()
        if i != n:
            return None
        return float(result)
    except (ValueError, ZeroDivisionError):
        return None

