def knapsack_01(items, capacity):
    # Guard against None and ensure iterable
    if items is None:
        items = []
    # Collect zero-weight positive-value items (can always be taken once each)
    zero_gain = 0
    filtered = []
    for w, v in items:
        if w <= 0:
            if w == 0 and v > 0:
                zero_gain += v
            # Skip non-positive weights to avoid invalid or infinite scenarios
            continue
        filtered.append((w, v))
    # If capacity is non-positive, only zero-weight gains are possible
    if capacity <= 0:
        return zero_gain
    # Dynamic programming array: dp[c] = max value with capacity c
    dp = [0] * (capacity + 1)
    for w, v in filtered:
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            val = dp[c - w] + v
            if val > dp[c]:
                dp[c] = val
    return dp[capacity] + zero_gain

